 $q=$pdo->prepare('SELECT * FROM NB_OfficialMeeting WHERE section_id=? ORDER BY ordinal');$q->execute([$row['id']]);$blocks=$q->fetchAll();section_check(count($blocks)===count($s['meetings']),'Every exact meeting block retained');foreach($s['meetings']as$i=>$m){$b=$blocks[$i];$meetings++;section_check($b['begin_time']===$m['beginTime']&&$b['end_time']===$m['endTime'],'Exact source times preserved');$stored=json_decode($b['source_json'],true);$same=count($stored)===count($m);foreach($m as$key=>$value)if(!array_key_exists($key,$stored)||$stored[$key]!==$value)$same=false;section_check($same,'Every meeting value/type retained');section_check($b['start_date']===\Northbridge\Academic\official_iso_date($m['startDate'])&&$b['end_date']===\Northbridge\Academic\official_iso_date($m['endDate']),'Part-of-term date boundaries preserved');}}
